import{_ as r,o as a,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"帖子与时间线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/posts.md","filePath":"guide/posts.md","lastUpdated":1789295632000}'),e={name:"guide/posts.md"};function o(l,t,n,d,g,h){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="帖子与时间线" tabindex="-1">帖子与时间线 <a class="header-anchor" href="#帖子与时间线" aria-label="Permalink to &quot;帖子与时间线&quot;">​</a></h1><p>帖子是平台的核心社交单元。你可以通过「发现」页浏览社区热门内容，也可以在「时间线」中查看关注的人或整个社区的动态。</p><p>帖子支持文字、文件、投票等内容。发布后，帖子会加入时间轴，你的关注者与服务器用户都可以看到。你可以对帖子做出反应，也可以回复和引用，或将帖子加到我的最爱，方便以后查阅。</p><p>在本站发帖还可以享受（？）来自 Aliya 的锐评。</p><h2 id="发现" tabindex="-1">发现 <a class="header-anchor" href="#发现" aria-label="Permalink to &quot;发现&quot;">​</a></h2><p>发现页是登录后的默认首页，帮你快速看到社区里最受欢迎的内容。</p><ul><li><strong>精选</strong>：展示热门帖子和投票，支持按「推荐」「热度」「最新」排序，无限滚动加载。</li><li><strong>用户</strong>：发现社区活跃用户。</li><li><strong>角色</strong>：浏览服务器角色。</li></ul><p>热度会随时间自然衰减，不会让老内容一直霸榜；推荐模式兼顾热门与新鲜内容，帮你发现更多好帖子。频道中的帖子也会出现在发现页，并标注来源频道。</p><h2 id="时间线" tabindex="-1">时间线 <a class="header-anchor" href="#时间线" aria-label="Permalink to &quot;时间线&quot;">​</a></h2><p>时间线提供多种视角来浏览帖子：</p><table tabindex="0"><thead><tr><th>类型</th><th>看到什么</th></tr></thead><tbody><tr><td>首页</td><td>你关注的人发的帖子</td></tr><tr><td>本地</td><td>所有人的帖子</td></tr><tr><td>社交</td><td>首页 + 本地 合并</td></tr><tr><td>全局</td><td>所有帖子</td></tr><tr><td>列表</td><td>你自建的用户列表</td></tr><tr><td>天线</td><td>按关键词/用户订阅的内容</td></tr><tr><td>频道</td><td>特定频道的内容</td></tr></tbody></table><p>你可以筛选是否显示转帖、回复、仅看带图帖子等。新帖子会实时推送，无需手动刷新。</p><p>列表与天线的用法见<a href="/guide/misskey/lists-antennas">列表与天线</a>，频道详见<a href="/guide/misskey/channels">频道</a>。</p><h2 id="发帖" tabindex="-1">发帖 <a class="header-anchor" href="#发帖" aria-label="Permalink to &quot;发帖&quot;">​</a></h2><p>点击发帖按钮即可发布内容，支持：</p><ul><li><strong>可见性</strong>：公开、仅首页、仅关注者、指定用户</li><li><strong>附件</strong>：图片、视频等文件，可标记为敏感内容</li><li><strong>投票</strong>：创建多选项投票</li><li><strong>内容警告</strong>：折叠正文，仅显示提示文字</li><li><strong>定时发布</strong>：设定未来时间自动发出</li><li><strong>草稿</strong>：暂时保存，稍后继续编辑</li><li><strong>话题标签</strong>：附加 #标签 方便他人发现</li><li><strong>频道投稿</strong>：发布到指定频道</li><li><strong>引用与回复</strong>：引用他人帖子附加评论，或直接在帖子下回复</li></ul><p>帖子正文支持 <a href="/guide/misskey/mfm">MFM 语法</a>，可以实现加粗、动画、配色等富文本效果。</p><h2 id="互动" tabindex="-1">互动 <a class="header-anchor" href="#互动" aria-label="Permalink to &quot;互动&quot;">​</a></h2><p>看到喜欢的帖子，你可以：</p><ul><li><strong>回应</strong>：用 Emoji 表达态度（不只是点赞），详见<a href="/guide/misskey/reactions">回应与表情符号</a></li><li><strong>转帖</strong>：分享到自己的时间线</li><li><strong>引用</strong>：转帖并加上自己的想法</li><li><strong>回复</strong>：参与讨论</li><li><strong>收藏 / 便签</strong>：保存喜欢的内容，详见<a href="/guide/misskey/clips-favorites">便签与收藏</a></li><li><strong>分享 / 举报</strong>：生成链接或向管理员反馈</li></ul>',20)])])}const c=r(e,[["render",o]]);export{u as __pageData,c as default};
